from mw_runtime import Session
s=Session()
s.move([.12,.431,0.0],gripper=-1,steps=40)
for _ in range(15):s.step([0,0,0,-1])
for _ in range(30):s.step([0,0,0,1])
for _ in range(60):s.step([0,0,.6,1])
for _ in range(75):s.step([0,.2,0,1])
for _ in range(3):s.step([-.2,0,0,1])
for _ in range(30):s.step([0,0,-.8,1])
for _ in range(16):
    s.step([0,1,0,1])
    if s.result()['success']:
        break
print('result',s.result())
assert s.result()['success'], 'replay did not reach success'
s.save('/app/output/trajectory.npz')
print('saved',s.total_steps,s.episodes)
